  const d = Math.max(0, +it.depth_ft || 0);
  const fd = Math.max(0, +it.footing_ft || 0);
  const w = Math.max(0, isFinite(+it.footing_w_ft) ? +it.footing_w_ft : 2);
  const hv = Math.max(0, isFinite(+it.layback_hv) ? +it.layback_hv : 1);
